const $=id=>document.getElementById(id);let zoom=100,hits=[],hitIndex=0,currentFile=null;const input=$('fileInput'),drop=$('dropzone'),doc=$('document');document.querySelectorAll('.open-trigger').forEach(b=>b.onclick=()=>input.click());drop.onclick=()=>input.click();input.onchange=()=>{if(input.files[0])openFile(input.files[0]);input.value=''};['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>{if(e.dataTransfer.files[0])openFile(e.dataTransfer.files[0])});function toast(message){const t=$('toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',6000)}
async function openFile(file){const legacy=/\.doc$/i.test(file.name);if(!legacy&&!/\.docx$/i.test(file.name)){toast('Please choose a .doc or .docx document.');return}if(!window.docx){toast('The document renderer could not load. Please check your connection and try again.');return}if(legacy&&file.size>20*1024*1024){toast('DOC files must be 20 MB or smaller.');return}try{toast(legacy?'Converting your DOC file on the server?':'Opening your document?');let buffer;if(legacy){let response=await fetch('/convert',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});if(!response.ok)throw new Error('The DOC file could not be converted. It may be damaged or password-protected.');buffer=await response.arrayBuffer()}else buffer=await file.arrayBuffer();doc.innerHTML='';await window.docx.renderAsync(buffer,doc,null,{inWrapper:true,breakPages:true,renderHeaders:true,renderFooters:true,renderFootnotes:true,renderEndnotes:true});currentFile=file;$('welcome').hidden=true;$('documentArea').hidden=false;$('filename').textContent=file.name;$('crumb').textContent=file.name;$('fileInfo').textContent=(file.size/1024).toFixed(0)+' KB  |  '+(legacy?'DOC':'DOCX');$('toast').style.display='none';buildOutline();setZoom();$('canvas').scrollTop=0}catch(e){console.error(e);toast(e.message||'Could not open this document. It may be damaged or password-protected.')}}
function buildOutline(){let headings=[...doc.querySelectorAll('h1,h2,h3,h4,h5,h6,p[class*=docx_heading],p.docx_title')].filter(x=>x.textContent.trim());let outline=$('outline');outline.innerHTML='';if(!headings.length){outline.innerHTML='<p>No headings found in this document.</p>';return}headings.forEach(h=>{let b=document.createElement('button');b.textContent=h.textContent.trim();b.onclick=()=>h.scrollIntoView({behavior:'smooth',block:'start'});outline.appendChild(b)})}function setZoom(){$('zoomLabel').textContent=zoom+'%';doc.style.zoom=zoom/100}$('zoomOut').onclick=()=>{zoom=Math.max(50,zoom-10);setZoom()};$('zoomIn').onclick=()=>{zoom=Math.min(150,zoom+10);setZoom()};$('print').onclick=()=>{if(currentFile)window.print();else toast('Open a document first.')};$('searchToggle').onclick=()=>{if(!currentFile){toast('Open a document first.');return}$('searchBar').hidden=false;$('searchInput').focus()};$('searchClose').onclick=()=>{$('searchBar').hidden=true;$('searchInput').value='';clearHits()};function clearHits(){hits.forEach(h=>h.replaceWith(document.createTextNode(h.textContent)));doc.normalize();hits=[];$('searchCount').textContent=''}function search(){clearHits();let q=$('searchInput').value.trim();if(!q)return;let walker=document.createTreeWalker(doc,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('style,script')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{let text=n.nodeValue,low=text.toLowerCase(),query=q.toLowerCase(),at=0,index,frag=document.createDocumentFragment(),found=false;while((index=low.indexOf(query,at))!==-1){found=true;frag.append(text.slice(at,index));let mark=document.createElement('mark');mark.className='search-hit';mark.textContent=text.slice(index,index+q.length);frag.append(mark);hits.push(mark);at=index+q.length}if(found){frag.append(text.slice(at));n.replaceWith(frag)}});hitIndex=0;showHit()}function showHit(){hits.forEach(h=>h.classList.remove('current'));$('searchCount').textContent=hits.length?`${hitIndex+1} / ${hits.length}`:'No matches';if(hits.length){hits[hitIndex].classList.add('current');hits[hitIndex].scrollIntoView({behavior:'smooth',block:'center'})}}$('searchInput').oninput=search;$('searchNext').onclick=()=>{if(hits.length){hitIndex=(hitIndex+1)%hits.length;showHit()}};$('searchPrev').onclick=()=>{if(hits.length){hitIndex=(hitIndex-1+hits.length)%hits.length;showHit()}};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'&&currentFile){e.preventDefault();$('searchToggle').click()}if(e.key==='Escape'&&!$('searchBar').hidden)$('searchClose').click()});
